// Generate non-NULL, null-terminated C strings for key and value
std::string key_str = FUZZ_PARAM_STR();
std::string val_str = FUZZ_PARAM_STR();
const char *key = key_str.c_str();
const char *value = val_str.c_str();

// Invoke target; returns newly allocated buffer on success
char *s = qs_stringify(key, value);

// Defensive: if allocation or handling failed, bail to avoid emitting a NULL output
if (!s) { FUZZ_BAIL(); }

// Track ownership and origin so qs_free can validate proper usage
FUZZ_SET_ATTR_INT(s, "qs_owned", 1);
FUZZ_SET_ATTR_STR(s, "origin", "stringify");
FUZZ_SET_ATTR_INT(s, "freed", 0);

// Validation summary: inputs satisfy non-NULL C-string requirement; output is non-NULL and marked as library-owned for safe later free.

// Build a plausible query string and a lookup key; ensure both are valid C strings
std::string k = FUZZ_PARAM_STR();
std::string v = FUZZ_PARAM_STR();
std::string noise1 = FUZZ_PARAM_STR();
std::string noise2 = FUZZ_PARAM_STR();

// Select a construction mode to exercise different parsing paths
unsigned mode = (*FUZZ_PARAM(unsigned int)) % 3u;
std::string query_str;
switch (mode) {
    case 0:
        // Exact key-value present
        query_str = k + "=" + v;
        break;
    case 1:
        // Mixed parameters; target key in the middle
        query_str = std::string("a=") + noise1 + "&" + k + "=" + v + "&b=" + noise2;
        break;
    default:
        // Duplicate and trailing separators
        query_str = k + "=" + v + "&" + k + "=" + noise1 + "&&c=" + noise2;
        break;
}

const char *query = query_str.c_str();
const char *key = k.c_str();

// Invoke target; may return NULL if not found or on error — we bail to avoid NULL outputs
char *s = qs_parse_value(query, key);
if (!s) { FUZZ_BAIL(); }

// Track ownership and origin so qs_free can validate proper usage
FUZZ_SET_ATTR_INT(s, "qs_owned", 1);
FUZZ_SET_ATTR_STR(s, "origin", "parse_value");
FUZZ_SET_ATTR_INT(s, "freed", 0);

// Validation summary: inputs are valid C-strings; non-NULL output is marked as library-owned to enable safe qs_free later.

// Enforce that s originated from this library and was not already freed
int owned = FUZZ_GET_ATTR_INT(s, "qs_owned");
int already_freed = FUZZ_GET_ATTR_INT(s, "freed");
if (owned != 1) { FUZZ_BAIL(); }
if (already_freed == 1) { FUZZ_BAIL(); }

// Mark as freed in metadata before releasing to prevent any accidental reuse
FUZZ_SET_ATTR_INT(s, "freed", 1);

// Invoke target free; do not return s as output to drop it from the pool
qs_free(s);

// Validation summary: only library-allocated, not-yet-freed pointers are accepted; pointer is dropped after free to avoid double free.

