import random
import string
from typing import List, Tuple

# This generator produces valid URL query strings intended to exercise qs_parse_value.
# The fuzzer stub constructs the final query from FUZZ_PARAM_STR pieces and a key/value.
# We therefore output a single buffer that, when used for FUZZ_PARAM_STR and filename
# by the harness, likely yields interesting combinations. Since the harness calls
# FUZZ_PARAM_STR multiple times, most fuzzing frameworks split the provided initial
# buffer into segments; we encode multiple newline-separated tokens so each call can
# consume a distinct, valid string. This approach avoids malformed UTF-8 assumptions
# but keeps everything ASCII and URL-safe.

SAFE_CHARS = string.ascii_letters + string.digits + "-_.*"
KEY_CHARS = string.ascii_letters + string.digits + "_-"

PCT_HEX = "0123456789ABCDEF"


def _rand_choice(rng: random.Random, s: str) -> str:
    return s[rng.randrange(len(s))]


def percent_encode(rng: random.Random, s: str, ratio: float) -> str:
    # Encode roughly ratio of characters as %HH; leave others intact.
    out = []
    for ch in s:
        if ch == ' ':
            # sometimes encode space as +
            if rng.random() < 0.5:
                out.append('+')
                continue
        if rng.random() < ratio:
            b = ord(ch) & 0xFF
            out.append('%')
            out.append(PCT_HEX[(b >> 4) & 0xF])
            out.append(PCT_HEX[b & 0xF])
        else:
            out.append(ch)
    return ''.join(out)


def make_key(rng: random.Random) -> str:
    # Keys common patterns: empty, simple, mixed, repeated words
    mode = rng.randrange(6)
    if mode == 0:
        return ""  # empty key path
    elif mode == 1:
        return "a"
    elif mode == 2:
        return "key"
    elif mode == 3:
        return "id_%d" % rng.randint(0, 999)
    elif mode == 4:
        # include dot and dash
        length = rng.randint(1, 12)
        chars = KEY_CHARS + ".-"
        return ''.join(rng.choice(chars) for _ in range(length))
    else:
        # mixed case
        length = rng.randint(1, 16)
        return ''.join(rng.choice(KEY_CHARS) for _ in range(length))


def make_value(rng: random.Random) -> str:
    mode = rng.randrange(7)
    if mode == 0:
        return ""
    elif mode == 1:
        return "0"
    elif mode == 2:
        return "true"
    elif mode == 3:
        return "hello world"  # has space to exercise '+' or %20
    elif mode == 4:
        # numbers and dots
        return "%d.%d" % (rng.randint(0, 9999), rng.randint(0, 9999))
    elif mode == 5:
        # path-like
        raw = "/".join(
            ''.join(rng.choice(SAFE_CHARS) for _ in range(rng.randint(1, 6)))
            for _ in range(rng.randint(1, 4))
        )
        return raw
    else:
        # random safe with occasional spaces
        length = rng.randint(0, 24)
        pool = SAFE_CHARS + " "
        raw = ''.join(rng.choice(pool) for _ in range(length))
        return raw


def maybe_encode(rng: random.Random, s: str) -> str:
    if not s:
        return s
    mode = rng.randrange(4)
    if mode == 0:
        return s  # plain
    elif mode == 1:
        return percent_encode(rng, s, ratio=0.3)
    elif mode == 2:
        # encode everything non-alnum
        out = []
        for ch in s:
            if ch.isalnum():
                out.append(ch)
            elif ch == ' ':
                out.append('+' if rng.random() < 0.7 else '%20')
            else:
                out.append('%' + format(ord(ch) & 0xFF, '02X'))
        return ''.join(out)
    else:
        # lowercase hex in percent-encoding sometimes
        enc = percent_encode(rng, s, ratio=0.6)
        # randomly lowercase hex digits after %
        tmp = []
        i = 0
        while i < len(enc):
            if enc[i] == '%' and i + 2 < len(enc):
                tmp.append('%')
                tmp.append(enc[i+1].lower() if rng.random() < 0.5 else enc[i+1])
                tmp.append(enc[i+2].lower() if rng.random() < 0.5 else enc[i+2])
                i += 3
            else:
                tmp.append(enc[i])
                i += 1
        return ''.join(tmp)


def make_noise(rng: random.Random) -> str:
    # arbitrary values for unrelated keys
    v = make_value(rng)
    return maybe_encode(rng, v)


def assemble_queries(rng: random.Random, k: str, v: str, noise1: str, noise2: str) -> List[str]:
    kv = f"{k}={v}"
    queries = []
    # Mode 0: exact key=value
    queries.append(kv)
    # Mode 1: mixed parameters, target in middle
    queries.append(f"a={noise1}&{kv}&b={noise2}")
    # Mode 2: duplicates and trailing separators
    queries.append(f"{kv}&{k}={noise1}&&c={noise2}")
    # Additional variants to widen coverage
    # repeated key three times
    queries.append(f"x=1&{kv}&{k}=&{k}={noise2}")
    # leading separator and empty assignment
    queries.append(f"&{kv}&&{k}=&=noval&{k}={noise1}")
    # key present without equal sign plus with value
    queries.append(f"flag&{kv}&{k}")
    return queries


def make_bundle(rng: random.Random) -> bytes:
    # Produce a bundle of tokens intended for FUZZ_PARAM_STR consumption.
    # We place: key, value, noise1, noise2, followed by several prebuilt query strings.
    key_raw = make_key(rng)
    val_raw = make_value(rng)
    noise1_raw = make_noise(rng)
    noise2_raw = make_noise(rng)

    # Encode key/value separately for realistic behavior
    key_enc = maybe_encode(rng, key_raw)
    val_enc = maybe_encode(rng, val_raw)

    queries = assemble_queries(rng, key_enc, val_enc, noise1_raw, noise2_raw)

    # Also include standalone tokens that the harness might pick up as FUZZ_PARAM_STR
    tokens: List[str] = []
    tokens.append(key_enc)
    tokens.append(val_enc)
    tokens.append(noise1_raw)
    tokens.append(noise2_raw)

    # Include some alternative encodings of the same key/value to test matching nuances
    tokens.append(maybe_encode(rng, key_raw))
    tokens.append(maybe_encode(rng, val_raw))

    # Append queries
    tokens.extend(queries)

    # Ensure total size constraint
    joined = "\n".join(tokens)
    b = joined.encode('utf-8', errors='strict')
    if len(b) > 4096:
        # trim from the end if oversized
        b = b[:4096]
    return b


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    return make_bundle(rng)
